232	// markNodeFailed removes a node from the in-memory list and notifies
233	// the OnNodeFailed callback. Subsequent calls (in this invocation)
234	// skip the removed node.
235	func (p *Proxy) markNodeFailed(node string) {
236		filtered := make([]string, 0, len(p.nodes))
237		for _, n := range p.nodes {
238			if n != node {
239				filtered = append(filtered, n)
240			}
241		}
242		p.nodes = filtered
243	
244		if p.onNodeFailed != nil {
245			p.onNodeFailed(node)
246		}
247	}
