249	// setAuthOrError applies the configured SetAuthFunc (if any) to the
250	// request. Errors come from the auth provider (core), not the data
251	// plane, so they short-circuit failover.
252	func (p *Proxy) setAuthOrError(req *http.Request) error {
253		if p.setAuth == nil {
254			return nil
255		}
256		// Hard chokepoint: every credential-bearing request flows through here.
257		// Even if a node URL slipped past the ingress filters, refuse to stamp a
258		// token onto a request bound for a host outside the cluster trust domain.
259		if !p.hostInCluster(req.URL.Hostname()) {
260			return fmt.Errorf("refusing to send credentials to out-of-cluster host %q (cluster %q)", req.URL.Hostname(), p.clusterHost)
261		}
262		return p.setAuth(req)
263	}
